/**
 * The emoji picker's catalogue and its search, for both apps: every emoji with its name and
 * keywords in French and in English (`design/emojiCatalogue.json`, generated by
 * tools/emoji/build_emoji.mjs; each app loads it the first time a picker opens). A search reads the
 * languages asked for, word by word, each word the start of a word of the emoji's name or keywords,
 * accents and case aside.
 */
export type EmojiLanguage = 'fr' | 'en';

export interface EmojiGroup {
  readonly key: string;
  readonly fr: string;
  readonly en: string;
}

export interface Emoji {
  readonly emoji: string;
  readonly group: number;
  /** Its name in each language. */
  readonly name: Readonly<Record<EmojiLanguage, string>>;
}

export interface EmojiCatalogue {
  readonly groups: readonly EmojiGroup[];
  readonly emojis: readonly Emoji[];
  /** Per emoji (same order) and language: the name, its keywords and every word of both, searchable. */
  readonly index: readonly Readonly<Record<EmojiLanguage, SearchText>>[];
}

interface SearchText {
  readonly name: string;
  readonly keywords: readonly string[];
  readonly words: readonly string[];
}

/** The generated file as it is stored: [emoji, group, French name, French keywords, English name, English keywords]. */
export type EmojiRow = readonly [emoji: string, group: number, frName: string, frKeywords: string, enName: string, enKeywords: string];

export interface EmojiCatalogueData {
  readonly groups: readonly EmojiGroup[];
  readonly emojis: readonly EmojiRow[];
}

/** `normalize('NFD')` is not guaranteed in Hermes: where it does nothing, accents go by table. */
const DECOMPOSES = (() => {
  try {
    return 'é'.normalize('NFD').length === 2;
  } catch {
    return false;
  }
})();

const ACCENTS: Readonly<Record<string, string>> = {
  à: 'a', â: 'a', ä: 'a', á: 'a', ã: 'a', å: 'a', ç: 'c', é: 'e', è: 'e', ê: 'e', ë: 'e', í: 'i', ì: 'i', î: 'i', ï: 'i',
  ñ: 'n', ó: 'o', ò: 'o', ô: 'o', ö: 'o', õ: 'o', ú: 'u', ù: 'u', û: 'u', ü: 'u', ý: 'y', ÿ: 'y',
};

/** Lower case, no accents, the ligatures spelled out (cœur, coeur), words split on anything that is not a letter or a digit. */
export function fold(text: string): string {
  const lower = DECOMPOSES ? text.normalize('NFD').replace(/\p{M}/gu, '').toLowerCase() : [...text.toLowerCase()].map(char => ACCENTS[char] ?? char).join('');
  return lower
    .replace(/œ/g, 'oe')
    .replace(/æ/g, 'ae')
    .replace(/ß/g, 'ss')
    .replace(/[^\p{L}\p{N}]+/gu, ' ')
    .trim();
}

function searchText(name: string, keywords: string): SearchText {
  const folded = keywords ? keywords.split('|').map(fold) : [];
  const own = fold(name);
  const words = new Set<string>();
  for (const phrase of [own, ...folded]) for (const word of phrase.split(' ')) if (word) words.add(word);
  return { name: own, keywords: folded, words: [...words] };
}

/** The generated file, ready to show and to search. */
export function buildEmojiCatalogue(data: EmojiCatalogueData): EmojiCatalogue {
  const emojis = data.emojis.map(([emoji, group, frName, , enName]) => ({ emoji, group, name: { fr: frName, en: enName } }));
  const index = data.emojis.map(([, , frName, frKeywords, enName, enKeywords]) => ({ fr: searchText(frName, frKeywords), en: searchText(enName, enKeywords) }));
  return { groups: data.groups, emojis, index };
}

/** How well one language's words answer the query; 0 when a word of the query finds nothing. */
function score(text: SearchText, query: string, words: readonly string[]): number {
  for (const word of words) if (!text.words.some(own => own.startsWith(word))) return 0;
  let points = 1;
  if (text.name === query) points += 100;
  // The shorter name first: "cœur rouge" before "cœur avec flèche".
  else if (text.name.startsWith(query)) points += 60 - Math.min(20, text.name.length - query.length) / 2;
  else if (text.name.split(' ').some(own => own.startsWith(words[0]!))) points += 30;
  if (text.keywords.includes(query)) points += 40;
  else if (text.keywords.some(keyword => keyword.startsWith(query))) points += 15;
  return points;
}

/** The everyday ones: first in the picker when nothing is typed, and first among equals in a search ("cœur": ❤️). */
export const EVERYDAY_EMOJI: readonly string[] = [
  '💡', '📌', '📝', '📚', '📖', '🗂️', '📁', '📎', '✅', '⭐', '🔥', '❤️',
  '💬', '❓', '❗', '⚠️', '🚧', '✨', '🎯', '🚀', '🧭', '🗺️', '✈️', '🏖️',
  '🏔️', '🏕️', '🚲', '🚆', '🏠', '🛋️', '🍳', '🥐', '🥗', '🍝', '🍷', '☕',
  '🍰', '🌱', '🌿', '🌳', '🌸', '🍂', '❄️', '☀️', '🌙', '🌊', '🐟', '🐦',
  '🐱', '🐶', '🎨', '🎵', '🎬', '📷', '🎮', '⚽', '🧘', '💪', '🩺', '💰',
  '🛒', '🎁', '🎉', '📅', '⏰', '📈', '💼', '🧾', '🔑', '🛠️', '💻', '🧠',
];

const EVERYDAY = new Set(EVERYDAY_EMOJI);

/** The emojis answering `query` in any of `languages`, best first (the everyday ones first among equals), then in the catalogue's order. */
export function searchEmoji(catalogue: EmojiCatalogue, query: string, languages: readonly EmojiLanguage[], limit = 160): Emoji[] {
  const folded = fold(query);
  const words = folded.split(' ').filter(Boolean);
  if (words.length === 0) return [];
  const found: { at: number; points: number }[] = [];
  catalogue.index.forEach((texts, at) => {
    let points = 0;
    for (const language of languages) points = Math.max(points, score(texts[language], folded, words));
    if (points > 0) found.push({ at, points: points + (EVERYDAY.has(catalogue.emojis[at]!.emoji) ? 25 : 0) });
  });
  found.sort((a, b) => b.points - a.points || a.at - b.at);
  return found.slice(0, limit).map(({ at }) => catalogue.emojis[at]!);
}

/** The name an emoji goes by in the first language asked for (French, unless only English is). */
export function emojiName(emoji: Emoji, languages: readonly EmojiLanguage[]): string {
  return emoji.name[languages[0] ?? 'fr'] || emoji.name.fr;
}

/** Whether a character is drawn as an emoji: by Unicode's property where the engine knows it, else by its block. */
const PICTOGRAPHIC = (() => {
  try {
    return new RegExp('\\p{Extended_Pictographic}|\\p{Regional_Indicator}', 'u');
  } catch {
    return /[\u{1F000}-\u{1FAFF}\u{2300}-\u{23FF}\u{2600}-\u{27BF}\u{2B00}-\u{2BFF}\u{2190}-\u{21FF}\u{3030}\u{303D}\u{3297}\u{3299}\u{00A9}\u{00AE}\u{203C}\u{2049}\u{2122}\u{2139}]/u;
  }
})();

const isRegional = (point: number): boolean => point >= 0x1f1e6 && point <= 0x1f1ff;
/** What may follow an emoji in the same character: a variation selector, a keycap, a skin tone, a flag's tag letters. */
const isExtender = (point: number): boolean => point === 0xfe0f || point === 0x20e3 || (point >= 0x1f3fb && point <= 0x1f3ff) || (point >= 0xe0020 && point <= 0xe007f);

/** The first emoji of a text, joiners, skin tone and flag pairs kept, where the engine has no `Intl.Segmenter` (Hermes). */
function firstEmoji(text: string): string {
  const points = [...text];
  const code = (at: number): number => points[at]?.codePointAt(0) ?? 0;
  if (isRegional(code(0))) return isRegional(code(1)) ? points[0]! + points[1]! : points[0]!;
  let end = 1;
  for (;;) {
    while (end < points.length && isExtender(code(end))) end += 1;
    if (code(end) === 0x200d && end + 1 < points.length) end += 2;
    else break;
  }
  return points.slice(0, end).join('');
}

/** `Intl.Segmenter`, typed here: not every target this file compiles for declares it. */
type GraphemeSegmenter = new (locale: string, options: { readonly granularity: 'grapheme' }) => { segment(text: string): Iterable<{ readonly segment: string }> };

/** What a pasted text holds when it is an emoji itself (its first one, joiners and skin tone kept), or null. */
export function typedEmoji(value: string): string | null {
  const text = value.trim();
  if (!PICTOGRAPHIC.test(text)) return null;
  const Segmenter = typeof Intl !== 'undefined' ? (Intl as unknown as { Segmenter?: GraphemeSegmenter }).Segmenter : undefined;
  const first = Segmenter ? new Segmenter('fr', { granularity: 'grapheme' }).segment(text)[Symbol.iterator]().next().value?.segment : firstEmoji(text);
  return first && PICTOGRAPHIC.test(first) ? first.slice(0, 32) : null;
}
